def box(x,y,w,h,c,t='',sz=16,tc=WHITE,r=8): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'+(text(x+w/2,y+h/2+sz*0.36,t,sz,tc) if t else '')
def person(x,y,s=1,shirt=BLUE,happy=True):
    mouth = '<path d="M-6 -22 q6 6 12 0" stroke="#000" stroke-width="2" fill="none"/>' if happy else '<path d="M-6 -18 q6 -6 12 0" stroke="#000" stroke-width="2" fill="none"/>'
    return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="-30" r="16" fill="{SKIN}"/><circle cx="-5" cy="-33" r="2" fill="#000"/><circle cx="5" cy="-33" r="2" fill="#000"/>{mouth}<rect x="-14" y="-14" width="28" height="36" rx="8" fill="{shirt}"/><rect x="-12" y="22" width="9" height="26" fill="{DGREY}"/><rect x="3" y="22" width="9" height="26" fill="{DGREY}"/><rect x="-24" y="-10" width="9" height="28" rx="4" fill="{SKIN}"/><rect x="15" y="-10" width="9" height="28" rx="4" fill="{SKIN}"/></g>'
def heart(x,y,s=1,c=RED): return f'<path transform="translate({x} {y}) scale({s})" d="M0 8 C-14 -4 -8 -16 0 -8 C8 -16 14 -4 0 8 Z" fill="{c}"/>'
def leaf(x,y,s=1,c=GREEN): return f'<path transform="translate({x} {y}) scale({s})" d="M0 0 C 10 -20 30 -20 34 0 C 30 20 10 20 0 0 Z" fill="{c}"/><line x1="{x}" y1="{y}" x2="{x+34*s}" y2="{y}" stroke="{DGREEN}" stroke-width="1.5"/>'
def fish(x,y,s=1,c=ORANGE): return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="0" cy="0" rx="26" ry="14" fill="{c}"/><polygon points="22,0 40,-14 40,14" fill="{c}"/><circle cx="-12" cy="-4" r="3" fill="#000"/><path d="M-8 4 q8 6 16 0" stroke="#000" stroke-width="1.5" fill="none"/></g>'
def bird(x,y,s=1,c=BLUE): return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="0" cy="0" rx="22" ry="14" fill="{c}"/><circle cx="20" cy="-10" r="10" fill="{c}"/><polygon points="28,-10 40,-7 28,-4" fill="{ORANGE}"/><circle cx="23" cy="-12" r="2" fill="#000"/><path d="M-6 -4 q-10 -16 10 -12" fill="{DGREEN}" opacity=".7"/><line x1="-4" y1="14" x2="-6" y2="26" stroke="{ORANGE}" stroke-width="3"/><line x1="6" y1="14" x2="8" y2="26" stroke="{ORANGE}" stroke-width="3"/></g>'
def dog(x,y,s=1,c=BROWN): return f'<g transform="translate({x} {y}) scale({s})"><rect x="-30" y="-10" width="56" height="30" rx="12" fill="{c}"/><circle cx="30" cy="-14" r="16" fill="{c}"/><ellipse cx="20" cy="-24" rx="6" ry="12" fill="{DBROWN}"/><circle cx="36" cy="-16" r="2.5" fill="#000"/><circle cx="44" cy="-8" r="4" fill="#000"/><rect x="-26" y="18" width="8" height="18" fill="{c}"/><rect x="-8" y="18" width="8" height="18" fill="{c}"/><rect x="8" y="18" width="8" height="18" fill="{c}"/><path d="M-30 -6 q-14 -14 -10 -26" stroke="{c}" stroke-width="6" fill="none"/></g>'
def frog(x,y,s=1): return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="0" cy="10" rx="34" ry="20" fill="{GREEN}"/><circle cx="-14" cy="-10" r="10" fill="{GREEN}"/><circle cx="14" cy="-10" r="10" fill="{GREEN}"/><circle cx="-14" cy="-11" r="5" fill="{WHITE}"/><circle cx="14" cy="-11" r="5" fill="{WHITE}"/><circle cx="-13" cy="-11" r="2.5" fill="#000"/><circle cx="15" cy="-11" r="2.5" fill="#000"/><path d="M-12 12 q12 8 24 0" stroke="#000" stroke-width="2" fill="none"/><ellipse cx="-34" cy="26" rx="12" ry="6" fill="{DGREEN}"/><ellipse cx="34" cy="26" rx="12" ry="6" fill="{DGREEN}"/></g>'
def bee(x,y,s=1): return f'<g transform="translate({x} {y}) scale({s})"><ellipse cx="-6" cy="-16" rx="12" ry="8" fill="{LBLUE}" opacity=".8"/><ellipse cx="8" cy="-16" rx="12" ry="8" fill="{LBLUE}" opacity=".8"/><ellipse cx="0" cy="0" rx="24" ry="14" fill="{YEL}"/><rect x="-10" y="-14" width="7" height="28" fill="#000"/><rect x="4" y="-14" width="7" height="28" fill="#000"/><circle cx="24" cy="-2" r="9" fill="#000"/><circle cx="27" cy="-5" r="2" fill="{WHITE}"/><line x1="-24" y1="0" x2="-32" y2="2" stroke="#000" stroke-width="2"/></g>'
def flower(x,y,s=1,c=PINK): return f'<g transform="translate({x} {y}) scale({s})"><line x1="0" y1="0" x2="0" y2="40" stroke="{DGREEN}" stroke-width="4"/>{"".join(f"<ellipse cx=\"{14*math.cos(a*math.pi/3):.1f}\" cy=\"{14*math.sin(a*math.pi/3):.1f}\" rx=\"9\" ry=\"7\" transform=\"rotate({a*60})\" fill=\"{c}\"/>" for a in range(6))}<circle cx="0" cy="0" r="7" fill="{YEL}"/></g>'
def monitor(x,y,w=120,h=80,screen=LBLUE): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{DGREY}"/><rect x="{x+6}" y="{y+6}" width="{w-12}" height="{h-18}" rx="4" fill="{screen}"/><rect x="{x+w/2-20}" y="{y+h}" width="40" height="10" fill="{GREY}"/><rect x="{x+w/2-36}" y="{y+h+10}" width="72" height="6" rx="3" fill="{DGREY}"/>'
def arrow(x1,y1,x2,y2,c=INK,w=3): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="{w}" marker-end="url(#ah)"/><defs><marker id="ah" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="{c}"/></marker></defs>'
